export class PulseCounter {
 count: number = 0
 loose(): boolean {
  return this.count == 2
 }
 strict(): boolean {
  return this.count === 2
 }
 assign(): void {
  this.count = 2
 }
 add(): void {
  this.count += 2
 }
 subtract(): void {
  this.count -= 2
 }
 increment(): void {
  this.count++
 }
 decrement(): void {
  this.count--
 }
 mixed(): void {
  if (this.count === 2) { this.count = 3 }
 }
}
